/**
 * Kumva Trigger Node with Scheduling
 * Initiates campaigns via schedule (cron, interval, once) or manual trigger
 */

module.exports = function(RED) {
  const csv = require('csvtojson');
  const schedule = require('node-schedule');
  const helpers = require('kumva-insights/utils/helpers');
  const DataStorage = require('kumva-insights/utils/data-storage');

  function KumvaTriggerNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;

    const storage = new DataStorage();
    let campaignId = null;
    let contacts = [];
    let currentIndex = 0;
    let triggerInterval = null;
    let campaignRunning = false;
    let scheduleJob = null;

    // Parse contacts from CSV, JSON, or manual input
    async function parseContacts() {
      try {
        const source = config.contactSource;
        contacts = [];

        switch(source) {
          case 'csv':
            if (!config.csvData || config.csvData.trim() === '') {
              return false;
            }
            contacts = await csv().fromString(config.csvData);
            break;

          case 'json':
            contacts = helpers.safeJsonParse(config.jsonData, []);
            if (!Array.isArray(contacts)) contacts = [];
            break;

          case 'manual':
            contacts = config.manualContacts
              .split('\n')
              .map(phone => phone.trim())
              .filter(phone => phone)
              .map(phone => ({ [config.phoneColumn]: phone }));
            break;

          default:
            return false;
        }

        contacts = contacts.filter(contact => {
          const phone = contact[config.phoneColumn];
          return phone && helpers.isValidPhoneNumber(phone);
        });

        return contacts.length > 0;
      } catch (error) {
        node.error(`Parse contacts error: ${error.message}`);
        return false;
      }
    }

    // Send next contact through flow
    function processNextContact() {
      if (currentIndex >= contacts.length) {
        completeCampaign();
        return;
      }

      const contact = contacts[currentIndex];
      currentIndex++;

      const initialMessage = helpers.resolveVariables(config.initialMessage, contact);

      const msg = {
        phoneNumber: contact[config.phoneColumn],
        contactData: contact,
        campaignId: campaignId,
        initialMessage: initialMessage,
        _kumva: {
          campaignId: campaignId,
          contactIndex: currentIndex - 1,
          totalContacts: contacts.length
        }
      };

      if (config.additionalFields) {
        config.additionalFields.split(',').map(f => f.trim()).forEach(field => {
          if (contact[field] !== undefined) {
            msg[field] = contact[field];
          }
        });
      }

      node.send(msg);
      node.status({
        fill: 'blue',
        shape: 'dot',
        text: `Processing ${currentIndex}/${contacts.length}`
      });
    }

    // Complete campaign and cleanup
    function completeCampaign() {
      if (triggerInterval) {
        clearInterval(triggerInterval);
        triggerInterval = null;
      }
      campaignRunning = false;

      storage.saveCampaign(campaignId, {
        name: config.name,
        totalContacts: contacts.length,
        completedAt: new Date().toISOString(),
        status: 'completed'
      });

      node.status({
        fill: 'green',
        shape: 'dot',
        text: `Complete (${contacts.length} contacts)`
      });
    }

    // Start campaign - fetch contacts and begin processing
    async function startCampaign() {
      try {
        if (campaignRunning) {
          node.warn('Campaign already running');
          return;
        }

        const parsed = await parseContacts();
        if (!parsed) {
          node.error('No valid contacts found');
          node.status({ fill: 'red', shape: 'dot', text: 'No valid contacts' });
          return;
        }

        campaignId = `campaign_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        campaignRunning = true;
        currentIndex = 0;

        storage.saveCampaign(campaignId, {
          name: config.name,
          totalContacts: contacts.length,
          startedAt: new Date().toISOString(),
          status: 'running'
        });

        node.status({
          fill: 'blue',
          shape: 'dot',
          text: `Starting (${contacts.length} contacts)`
        });

        const rateLimit = config.rateLimit || 60;
        const intervalMs = (60000 / rateLimit);

        triggerInterval = setInterval(() => {
          processNextContact();
        }, intervalMs);

        processNextContact();

      } catch (error) {
        node.error(`Campaign error: ${error.message}`);
        node.status({ fill: 'red', shape: 'dot', text: 'Error' });
      }
    }

    // Setup schedule if configured
    function setupSchedule() {
      if (config.scheduleType === 'none') {
        return;
      }

      try {
        if (config.scheduleType === 'cron') {
          scheduleJob = schedule.scheduleJob(config.cronExpression, startCampaign);
          node.log(`Scheduled: ${config.cronExpression}`);
        } else if (config.scheduleType === 'interval') {
          const intervalMs = helpers.getTimeoutMs(config.intervalTime);
          scheduleJob = setInterval(startCampaign, intervalMs);
          node.log(`Scheduled: every ${config.intervalTime}`);
        } else if (config.scheduleType === 'once') {
          const delayMs = helpers.getTimeoutMs(config.delayTime);
          scheduleJob = setTimeout(startCampaign, delayMs);
          node.log(`Scheduled: in ${config.delayTime}`);
        }
      } catch (error) {
        node.error(`Schedule setup error: ${error.message}`);
      }
    }

    // Handle manual input
    node.on('input', function(msg) {
      if (msg.payload === 'start' || msg.trigger === true) {
        startCampaign();
      } else if (msg.payload === 'stop' || msg.trigger === false) {
        if (triggerInterval) {
          clearInterval(triggerInterval);
          triggerInterval = null;
        }
        campaignRunning = false;
        node.status({ fill: 'orange', shape: 'dot', text: 'Stopped' });
      }
    });

    // Setup initial schedule
    setupSchedule();

    // Register manual trigger button endpoint
    RED.httpAdmin.post(`/kumva/trigger/${node.id}/start`, (req, res) => {
      startCampaign();
      res.json({ success: true });
    });

    RED.httpAdmin.post(`/kumva/trigger/${node.id}/stop`, (req, res) => {
      if (triggerInterval) {
        clearInterval(triggerInterval);
        triggerInterval = null;
      }
      campaignRunning = false;
      node.status({ fill: 'orange', shape: 'dot', text: 'Stopped' });
      res.json({ success: true });
    });

    node.on('close', function() {
      if (triggerInterval) clearInterval(triggerInterval);
      if (scheduleJob) {
        if (scheduleJob.cancel) scheduleJob.cancel();
        else clearTimeout(scheduleJob);
      }
      campaignRunning = false;
    });

    node.status({ fill: 'yellow', shape: 'ring', text: 'Ready to trigger' });
  }

  RED.nodes.registerType('kumva-trigger', KumvaTriggerNode);
};